const CF_API_URL = "https://mt-preorder-api.sorndee-a.workers.dev";

// ==========================================
// 🌟 ฟังก์ชันตัวช่วยสร้าง Dropdown กลุ่ม Wechat (โหลดสดใหม่เสมอ)
// ==========================================
window.populateWechatDropdown = function(selectId, defaultText = "เลือกกลุ่ม Wechat...", selectedValue = "") {
    let sel = document.getElementById(selectId);
    if (!sel) return;
    
    // กำหนดกลุ่มเริ่มต้นให้ทันที ถ้าระบบยังไม่มีข้อมูล
    if (!sysData.config) sysData.config = {};
    if (!sysData.config.wechatGroups || sysData.config.wechatGroups.length === 0) {
        sysData.config.wechatGroups = [
            "My Toys_Ping", "Mytoys-โกดังอี๊อู", "กวางโจว-น้องซี", 
            "ซานริโอ้81632", "ซัวเถา (คุณวิน)", "กระเป๋าแบรนด์", 
            "Ai แว่น", "ขวดน้ำ Yiwu"
        ];
    }
    
    let groups = sysData.config.wechatGroups;
    let wHtml = `<option value="" ${selectedValue === '' ? 'disabled selected' : ''}>${defaultText}</option>`;
    
    // วนลูปวาด Dropdown จากข้อมูลล่าสุดเสมอ
    groups.forEach(g => { 
        wHtml += `<option value="${g}" ${selectedValue === g ? 'selected' : ''}>${g}</option>`; 
    });
    
    sel.innerHTML = wHtml;
};

// ==========================================
// 🌟 ฟังก์ชันช่วยเหลือ: แยกแยะ Preorder vs Preorder BKK และ กรองรอบฐานข้อมูล
// ==========================================
window.isBkkSku = function(sku) {
    if (!sku) return false;
    // หาตัวอักษรภาษาอังกฤษตัวสุดท้าย (จากขวาไปซ้าย) ว่าเป็น P หรือไม่
    let match = sku.match(/[A-Za-z](?!.*[A-Za-z])/); 
    return match && match[0].toUpperCase() === 'P';
};

window.isDateInCycle = function(dateStr) {
    let cycles = (sysData.config && sysData.config.cycles) ? sysData.config.cycles : [];
    if (cycles.length === 0) return true; 
    
    let dTime = new Date(dateStr).getTime();
    if (isNaN(dTime)) return true; 
    
    for (let c of cycles) {
        let sTime = new Date(c.start).getTime();
        let eTime = new Date(c.end).getTime() + 86399999; // +เวลาให้ครอบคลุมถึงสิ้นวัน
        if (dTime >= sTime && dTime <= eTime) {
            return true;
        }
    }
    return false;
};

// ==========================================
// 🌟 ระบบป้องกันการปิด/รีเฟรชหน้าเว็บ หากมีการแก้ไขแต่ยังไม่ได้บันทึก
// ==========================================
let hasUnsavedData = false;

  window.addEventListener('beforeunload', function (e) {
    if (hasUnsavedData) {
      e.preventDefault();
      e.returnValue = ''; // บังคับให้เบราว์เซอร์แสดงหน้าต่างแจ้งเตือนมาตรฐาน
    }
  });

  window.markDataAsUnsaved = function() {
    hasUnsavedData = true;
  };

  window.clearUnsavedData = function() {
    hasUnsavedData = false;
  };

  // ฟังก์ชันเช็คก่อนเปลี่ยนแท็บ หรือเปลี่ยนหมวดหมู่ภายในเว็บ
  window.checkUnsavedBeforeNavigate = function(onProceedCallback) {
    if (hasUnsavedData) {
      showAppleConfirm(
        "ข้อมูลยังไม่ถูกบันทึก",
        "คุณมีการเปลี่ยนแปลงที่ยังไม่ได้บันทึก\nต้องการละทิ้งข้อมูลนี้ และทำรายการต่อหรือไม่?",
        "ละทิ้งข้อมูล",
        true, // เป็นปุ่มสีแดง (Destructive)
        function() {
          clearUnsavedData(); // เคลียร์สถานะ
          onProceedCallback(); // ดำเนินการโค้ดต่อ
        }
      );
    } else {
      // ถ้าไม่มีค้าง ให้ทำงานต่อทันที
      onProceedCallback();
    }
  };

  function safeDateMs(dateStr) {
    if (!dateStr) return 0;
    let d = new Date(dateStr);
    if (!isNaN(d.getTime())) return d.getTime(); 

    // 🌟 ดักจับ Object ที่หลุดเข้ามาและแปลงให้ปลอดภัยก่อนใช้ split
    let safeStr = String(dateStr || '');
    let parts = safeStr.split('/');
    if (parts.length === 3) {
      return new Date(parts[2], parts[1] - 1, parts[0]).getTime();
    }
    return 0;
  }

  // ==========================================
  // 🌟 ระบบแจ้งเตือนและยืนยันสไตล์ Apple (Core Alert System)
  // ==========================================
  function showAppleConfirm(title, message, confirmText, isDestructive, onConfirm) {
    document.getElementById('sysAlertTitle').innerText = title; 
    document.getElementById('sysAlertMessage').innerText = message;
    
    const iconEl = document.getElementById('sysAlertIcon');
    iconEl.innerHTML = isDestructive 
      ? '<svg width="50" height="50" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="10" fill="#ff3b30"/><path d="M12 8v4" stroke="#fff" stroke-width="2.5" stroke-linecap="round"/><circle cx="12" cy="16" r="1.5" fill="#fff"/></svg>' 
      : '<svg width="50" height="50" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="10" fill="#007aff"/><path d="M12 16v-4" stroke="#fff" stroke-width="2.5" stroke-linecap="round"/><circle cx="12" cy="8" r="1.25" fill="#fff"/></svg>';
    iconEl.style.display = 'flex';
    
    const btnContainer = document.getElementById('sysAlertButtons'); 
    btnContainer.innerHTML = ''; 
    
    const cancelBtn = document.createElement('button'); 
    cancelBtn.className = 'btn btn-secondary'; 
    cancelBtn.innerText = 'ยกเลิก'; 
    cancelBtn.onclick = () => closeModal('sysAlertModal'); 
    
    const confirmBtn = document.createElement('button'); 
    confirmBtn.className = isDestructive ? 'btn btn-danger' : 'btn btn-primary'; 
    confirmBtn.innerText = confirmText; 
    confirmBtn.onclick = () => { closeModal('sysAlertModal'); onConfirm(); }; 
    
    btnContainer.appendChild(cancelBtn); 
    btnContainer.appendChild(confirmBtn); 
    openModal('sysAlertModal');
  }

  function showAppleAlert(title, message) {
    document.getElementById('sysAlertTitle').innerText = title; 
    document.getElementById('sysAlertMessage').innerText = message;
    
    const iconEl = document.getElementById('sysAlertIcon');
    iconEl.innerHTML = title.includes("สำเร็จ") 
      ? '<svg width="50" height="50" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="10" fill="#34c759"/><path d="M16 9l-5.5 5.5L8 12" stroke="#fff" stroke-width="3" stroke-linecap="round"/></svg>' 
      : '<svg width="50" height="50" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="10" fill="#ff3b30"/><path d="M12 8v4" stroke="#fff" stroke-width="2.5" stroke-linecap="round"/><circle cx="12" cy="16" r="1.5" fill="#fff"/></svg>';
    iconEl.style.display = 'flex';
    
    const btnContainer = document.getElementById('sysAlertButtons'); 
    btnContainer.innerHTML = ''; 
    
    const okBtn = document.createElement('button'); 
    okBtn.className = title.includes("สำเร็จ") ? 'btn btn-primary' : 'btn btn-danger'; 
    okBtn.innerText = 'ตกลง'; 
    okBtn.onclick = () => closeModal('sysAlertModal'); 
    
    btnContainer.appendChild(okBtn); 
    openModal('sysAlertModal');
  }

  // 🌟 เขียนทับคำสั่ง alert() ของระบบ ให้ใช้ showAppleAlert แทนอัตโนมัติ
  window.alert = function(message) {
    let title = (message.includes("สำเร็จ") || message.includes("เรียบร้อย")) ? "สำเร็จ" : "ข้อผิดพลาด";
    showAppleAlert(title, message);
  };

  // ==========================================
// 🌟 ฟังก์ชันแจ้งเตือนสไตล์ Apple พร้อมปุ่ม Action (เช่น พาไปอีกหน้า)
// ==========================================
function showAppleAlertWithAction(title, message, actionText, onActionClick) {
  document.getElementById('sysAlertTitle').innerText = title; 
  document.getElementById('sysAlertMessage').innerText = message;
  
  const iconEl = document.getElementById('sysAlertIcon');
  // ใช้ไอคอนเครื่องหมายถูกสีเขียว (Success)
  iconEl.innerHTML = '<svg width="50" height="50" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="10" fill="#34c759"/><path d="M16 9l-5.5 5.5L8 12" stroke="#fff" stroke-width="3" stroke-linecap="round"/></svg>';
  iconEl.style.display = 'flex';
  
  const btnContainer = document.getElementById('sysAlertButtons'); 
  btnContainer.innerHTML = ''; 
  
  // ปุ่มที่ 1: ตกลง (ปิดหน้าต่างเฉยๆ)
  const closeBtn = document.createElement('button'); 
  closeBtn.className = 'btn btn-secondary'; 
  closeBtn.innerText = 'ตกลง'; 
  closeBtn.onclick = () => closeModal('sysAlertModal'); 
  
  // ปุ่มที่ 2: ปุ่ม Action (ปุ่มหลักสีฟ้า พาไป Modal)
  const actionBtn = document.createElement('button'); 
  actionBtn.className = 'btn btn-primary'; 
  actionBtn.innerText = actionText; 
  actionBtn.onclick = () => { 
     closeModal('sysAlertModal'); 
     onActionClick(); // เรียกใช้ฟังก์ชันที่ส่งเข้ามา
  }; 
  
  btnContainer.appendChild(closeBtn); 
  btnContainer.appendChild(actionBtn); 
  openModal('sysAlertModal');
}

  // 🌟 ฟังก์ชันจำลอง Confirm สไตล์ Apple (ใช้กับปุ่มลบโดยเฉพาะ)
  function showSysConfirm(message, onConfirmCallback, title = "ยืนยันการทำรายการ") {
    document.getElementById('sysConfirmTitle').innerHTML = title;
    document.getElementById('sysConfirmMsg').innerHTML = message;
    
    let confirmBtn = document.getElementById('sysConfirmBtn');
    // ล้างเหตุการณ์คลิกเก่าๆ ออกก่อน
    let newBtn = confirmBtn.cloneNode(true);
    confirmBtn.parentNode.replaceChild(newBtn, confirmBtn);
    
    newBtn.onclick = function() {
      closeModal('sysConfirmModal');
      if (typeof onConfirmCallback === "function") onConfirmCallback();
    };
    
    openModal('sysConfirmModal');
  }

