  window.showAuthAlert = function(title, message) {
      let isSuccess = title.includes("สำเร็จ") && !title.includes("ไม่สำเร็จ");
      
      document.getElementById('authAlertTitle').innerText = title; 
      document.getElementById('authAlertMessage').innerText = message;
      
      const iconEl = document.getElementById('authAlertIcon');
      // กำหนดไอคอน (สำเร็จ = สีเขียวติ๊กถูก / มีปัญหา = สีแดงกากบาท)
      iconEl.innerHTML = isSuccess 
        ? '<svg width="55" height="55" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="10" fill="#34c759"/><path d="M16 9l-5.5 5.5L8 12" stroke="#fff" stroke-width="3" stroke-linecap="round"/></svg>' 
        : '<svg width="55" height="55" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="10" fill="#ff3b30"/><path d="M12 8v4" stroke="#fff" stroke-width="2.5" stroke-linecap="round"/><circle cx="12" cy="16" r="1.5" fill="#fff"/></svg>';
      
      let overlay = document.getElementById('authAlertOverlay');
      let box = document.getElementById('authAlertBox');
      
      overlay.style.display = 'flex';
      setTimeout(() => {
          box.style.transform = 'scale(1)';
          box.style.opacity = '1';
      }, 10);
  };

  window.closeAuthAlert = function() {
      let overlay = document.getElementById('authAlertOverlay');
      let box = document.getElementById('authAlertBox');
      
      box.style.transform = 'scale(0.95)';
      box.style.opacity = '0';
      setTimeout(() => {
          overlay.style.display = 'none';
      }, 300);
  };

  let sysData = { config: { exRate: 5, catPercents: {}, vrich: '', cycles: [] }, categories: [], products: [] };
  let currentDetailUID = null;

  // ==========================================
  // 🌟 ระบบ Authentication & Role Management (SPA 100% ไม่มี Reload)
  // ==========================================
  window.regBase64Profile = "";
  window.otpCountdownInterval = null;

  document.addEventListener('DOMContentLoaded', () => {
      window.checkAuthStatus();
      window.setupProfileDragDrop();

      // 🌟 ดักจับ switchPage ของเดิม เพื่อตรวจสอบสิทธิ์การเข้าหน้า 6
      setTimeout(() => {
        if (typeof window.switchPage === 'function' && !window.originalSwitchPageApp) {
            window.originalSwitchPageApp = window.switchPage;
            window.switchPage = function(pageNo) {
                let currentUser = JSON.parse(localStorage.getItem('mt_user'));
                
                // 🌟 บล็อกการเข้าถึงหน้า 6 และ 7 ถ้าไม่ใช่ Admin
                if ((pageNo === 6 || pageNo === 7) && (!currentUser || currentUser.role !== 'Administrator')) {
                    if(typeof window.showAppleAlert === 'function') window.showAppleAlert("ปฏิเสธการเข้าถึง", "คุณไม่มีสิทธิ์เข้าถึงหน้านี้");
                    return;
                }
                
                if (pageNo === 6 && typeof window.loadRoleManagement === 'function') window.loadRoleManagement();
                if (pageNo === 7 && typeof window.fetchAndRenderLogs === 'function') window.fetchAndRenderLogs(); // 🌟 โหลด Log ทันทีที่กดเข้าหน้า
                
                window.originalSwitchPageApp(pageNo);
            };
        }
      }, 1000);
  });

  // ==========================================
  // 🌟 2. ฟังก์ชันตรวจสอบสถานะ (อัปเดตรูปเมนูมุมขวาบน)
  // ==========================================
  window.checkAuthStatus = function() {
      let user = JSON.parse(localStorage.getItem('mt_user'));
      let authContainer = document.getElementById('authContainer');
      let mainNavbar = document.getElementById('mainNavbar');

      if (!user) {
          if(authContainer) authContainer.style.display = 'flex';
          if(mainNavbar) mainNavbar.style.display = 'none';
          document.querySelectorAll('.container').forEach(c => c.style.display = 'none');
      } else {
          if(authContainer) authContainer.style.display = 'none';
          if(mainNavbar) mainNavbar.style.display = 'flex';
          document.querySelectorAll('.container').forEach(c => c.style.display = '');
          
          let accessStr = String(user.PageAccess || user.pageAccess || '1,2,3,4,5,8');
          let accessArr = accessStr === '' ? [] : accessStr.split(',').map(Number);
          
          let lastPage = parseInt(localStorage.getItem('mt_last_active_page'));
          let startPage = accessArr.length > 0 ? accessArr[0] : (user.role === 'Administrator' ? 6 : 1);
          
          if (lastPage && (accessArr.includes(lastPage) || (user.role === 'Administrator' && (lastPage === 6 || lastPage === 7)))) {
              startPage = lastPage;
          }

          if(typeof window.switchPage === 'function') window.switchPage(startPage);
          
          if(typeof window.loadData === 'function') window.loadData();
          if(typeof window.initFlatpickr === 'function') window.initFlatpickr();
          if(typeof window.startBackgroundPolling === 'function') {
              window.isPollingPaused = false;
              window.startBackgroundPolling();
          }
          if(typeof window.applyRoleRestrictions === 'function') window.applyRoleRestrictions(user);
          
          let navName = document.getElementById('navUserName');
          let nName = user.Nickname || user.nickname || '';
          if(navName) navName.innerText = `สวัสดี คุณ ${nName}`;
          
          let navRole = document.getElementById('navUserRole');
          if(navRole) navRole.innerText = user.role;
          
          let navPic = document.getElementById('navUserProfilePic');
          if(navPic) {
              let rawPic = user.ProfilePic || user.profilePic || "";
              navPic.src = rawPic ? getDirectImgUrl(rawPic) : "https://ui-avatars.com/api/?name=" + encodeURIComponent((user.username||"U").substring(0,2)) + "&background=e0f0ff&color=007aff";
          }
      }
  };

