          btnO.className = (type === 'otp') ? 'btn active' : 'btn';
          btnO.style.background = (type === 'otp') ? '#fff' : 'transparent';
          btnO.style.color = (type === 'otp') ? '#1d1d1f' : '#8e8e93';
