  // 🌟 ฟังก์ชันบันทึกข้อมูลการตรวจสอบพัสดุ (ส่ง Data ไปที่ Code.gs)
  window.saveDeliverySlipAndArrival = function() {
      let s = sysData.shipments[currentUploadRealIdx];
      
      // ดึงค่าการตรวจนับกล่อง
      let actualVal = document.getElementById('inp_boxActual').value;
      s.actualBoxCount = actualVal === '' ? null : parseFloat(actualVal);
      
      // ดึงสถานะ Toggle ยืนยันพัสดุ
      s.isDeliveryMatched = document.getElementById('chk_deliveryMatch').checked;
      
      window.clearUnsavedData();
      closeModal('deliverySlipModal');
      checkLotUnlockStatus(currentUploadRealIdx);
      
      // ส่งค่าไปบันทึกลง Google Sheet
      saveShipmentCheckExt(currentUploadRealIdx, s.shipId, true);
  };

  // ==========================================
  // 🌟 3. ฟังก์ชันอัปเดตข้อมูลการตรวจสอบพัสดุ (ตรวจนับจำนวนกล่อง)
  // ==========================================
  window.saveShipmentCheckExt = async function(realIdx, shipId, isSilent = false) {
  let realShip = sysData.shipments[realIdx];
  let updatedItems = realShip.items; 

  let newDeliverySlips = (realShip.deliverySlipImages || []).filter(img => typeof img === 'object' && img.base64);
  let newArrivalProds = (realShip.arrivalProductImages || []).filter(img => typeof img === 'object' && img.base64);
  let oldDeliverySlips = (realShip.deliverySlipImages || []).filter(img => typeof img === 'string');
  let oldArrivalProds = (realShip.arrivalProductImages || []).filter(img => typeof img === 'string');

  if (!isSilent) openModal('loader');
  
  let uploadT = realShip.deliveryUploadTime || "";
  let confirmT = realShip.deliveryConfirmTime || "";
  let arrUploadT = realShip.arrivalUploadTime || ""; 
  let actBox = realShip.actualBoxCount !== undefined ? realShip.actualBoxCount : null; 

  try {
      let finalDelSlips = [...oldDeliverySlips];
      let finalArrProds = [...oldArrivalProds];

      if (newDeliverySlips.length > 0 || newArrivalProds.length > 0) {
          let allUploads = [...newDeliverySlips, ...newArrivalProds];
          let uploadedUrls = await uploadImagesToCloudflare(allUploads);
          finalDelSlips = finalDelSlips.concat(uploadedUrls.slice(0, newDeliverySlips.length));
          finalArrProds = finalArrProds.concat(uploadedUrls.slice(newDeliverySlips.length));
      }

      const response = await fetch(`${CF_API_URL}/updateShipmentCheckData`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
              shipId: shipId,
              updatedItems: updatedItems,
              deliverySlips: finalDelSlips,
              arrivalProds: finalArrProds,
              isDeliveryMatched: realShip.isDeliveryMatched,
              uploadT: uploadT,
              confirmT: confirmT,
              arrUploadT: arrUploadT,
              actBox: actBox
          })
      });

      if (!response.ok) throw new Error("HTTP error " + response.status);
      const result = await response.json();

      if (!isSilent) {
          closeModal('loader');
          addSystemLog(`บันทึกข้อมูลการตรวจสอบ: อ้างอิง Lot ${shipId} เรียบร้อยแล้ว (ผ่าน CF)`);
          
          if (result.affectedGRs && result.affectedGRs.length > 0) {
              let alertMsg = `${result.message}\n\n⚠️ มีการอัปเดตข้อมูลส่งผลกระทบกับใบตรวจรับพัสดุ กรุณาดาวน์โหลดเอกสารต่อไปนี้ใหม่:\n- ` + result.affectedGRs.join('\n- ');
              showAppleAlertWithAction("สำเร็จ (มีข้อความแจ้งเตือน)", alertMsg, "จัดการใบตรวจรับพัสดุ", function() {
                  openModal('loader');
                  fetch(`${CF_API_URL}/getAppData`).then(r=>r.json()).then(newData => {
                      sysData = newData;
                      closeModal('loader');
                      openGoodsReceiptModal();
                      isViewingGrHistory = true;
                      document.getElementById('btnGrCreateNew').style.display = 'inline-flex';
                      document.getElementById('grNewItemsBadge').style.display = 'none';
                      document.getElementById('grHistoryViewBadge').style.display = 'inline-block';
                      document.getElementById('txtDownloadGR').innerText = 'ดาวน์โหลด PDF (ฉบับเดิม)';
                      renderGrHistorySidebar(); 
                  });
              });
          } else {
              showAppleAlert("สำเร็จ", result.message);
          }
      }
      loadDataBackground(); 

  } catch (err) {
      if (!isSilent) {
          closeModal('loader');
          showAppleAlert("ข้อผิดพลาด", err.message);
      }
  }
};

  // --- อัปโหลดภาพใบส่งของ (เก็บไว้ในระบบชั่วคราว รอดยืนยัน) ---
  window.handleDeliverySlipFiles = function(input) {
      window.markDataAsUnsaved();
      if(!input.files) return;
      let s = sysData.shipments[currentUploadRealIdx];
      if (!s.deliverySlipImages) s.deliverySlipImages = [];
      
      let promises = [];
      for(let i=0; i<input.files.length; i++) {
          let file = input.files[i];
          promises.push(new Promise((resolve) => {
              let reader = new FileReader();
              reader.onload = e => {
                  s.deliverySlipImages.push({ name: file.name, mime: file.type, base64: e.target.result });
                  resolve();
              };
              reader.readAsDataURL(file);
          }));
      }
      
      Promise.all(promises).then(() => {
          input.value = '';
          
          // อัปเดตเวลาให้หน้าจอ (ยังไม่เซฟลงฐานข้อมูลจนกว่าจะกดยืนยัน)
          let timeNow = getFormattedTimestamp();
          s.deliveryUploadTime = timeNow;
          let uploadLabel = document.getElementById('delModal_uploadTime');
          if (uploadLabel) {
              uploadLabel.innerText = `อัปโหลดล่าสุด: ${timeNow}`;
              uploadLabel.style.display = 'block';
          }
          
          renderDeliverySlipImgs();
      });
  }

  // --- ลบภาพใบส่งของ ---
  window.removeDeliverySlipImg = function(idx) {
      window.markDataAsUnsaved();
      let s = sysData.shipments[currentUploadRealIdx];
      s.deliverySlipImages.splice(idx, 1);
      renderDeliverySlipImgs();
      
      // ถ้าลบรูปจนหมด ให้รีเซ็ตสถานะยืนยัน และล็อกตามเดิม
      if (s.deliverySlipImages.length === 0) {
          s.isDeliveryMatched = false;
          s.deliveryConfirmTime = ""; 
          let confTimeEl = document.getElementById('delModal_confirmTime');
          if (confTimeEl) confTimeEl.style.display = 'none';
      }
      checkLotUnlockStatus(currentUploadRealIdx);
  }

  // --- ยืนยันว่าภาพตรงกัน (และบันทึกลง Google Sheet) ---
  window.confirmDeliveryMatch = function() {
      let s = sysData.shipments[currentUploadRealIdx];
      if(!s.deliverySlipImages || s.deliverySlipImages.length === 0) {
          showAppleAlert("แจ้งเตือน", "กรุณาอัปโหลดใบส่งของอย่างน้อย 1 ภาพก่อนกดยืนยันครับ");
          return;
      }
      
      s.isDeliveryMatched = true;
      let timeNow = getFormattedTimestamp();
      s.deliveryConfirmTime = timeNow; 
      
      let confirmLabel = document.getElementById('delModal_confirmTime');
      if (confirmLabel) {
          confirmLabel.innerText = `ยืนยันเมื่อ: ${timeNow}`;
          confirmLabel.style.display = 'block';
      }
      window.clearUnsavedData();
      closeModal('deliverySlipModal');
      checkLotUnlockStatus(currentUploadRealIdx);
      
      // 🌟 บันทึกลง Google Sheet ทันทีที่กดยืนยัน
      window.saveShipmentCheck(currentUploadRealIdx, s.shipId, true);
      showAppleAlert("สำเร็จ", "ยืนยันข้อมูลใบส่งของตรงกันเรียบร้อยแล้ว");
  }

