  // --- ฟังก์ชันอัปเดต UI เปิด/ปิด ล็อกทันที (ต้องครบ 3 เงื่อนไข) ---
  window.checkLotUnlockStatus = function(realIdx) {
      let s = sysData.shipments[realIdx];
      
      // 🌟 เช็คเงื่อนไขให้ครบ 3 อย่าง:
      // 1. มีภาพใบส่งของ
      // 2. กดยืนยันแล้ว (isDeliveryMatched)
      // 3. มีภาพรูปสินค้าจริง
      let hasDelSlip = s.deliverySlipImages && s.deliverySlipImages.length > 0;
      let isMatched = s.isDeliveryMatched === true;
      let hasArrProd = s.arrivalProductImages && s.arrivalProductImages.length > 0;
      
      let isUnlocked = hasDelSlip && isMatched && hasArrProd;
      
      let gridContainer = document.getElementById(`lot_grid_container_${realIdx}`);
      let statusTextEl = document.getElementById(`lot_status_${realIdx}`);
      
      let iconUnlock = `<svg viewBox="0 0 24 24" width="14" height="14" stroke="currentColor" stroke-width="2.5" fill="none" stroke-linecap="round" stroke-linejoin="round" style="vertical-align: text-bottom; margin-right: 4px;"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path><polyline points="22 4 12 14.01 9 11.01"></polyline></svg>`;
      let iconLock = `<svg viewBox="0 0 24 24" width="14" height="14" stroke="currentColor" stroke-width="2.5" fill="none" stroke-linecap="round" stroke-linejoin="round" style="vertical-align: text-bottom; margin-right: 4px;"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect><path d="M7 11V7a5 5 0 0 1 10 0v4"></path></svg>`;

      if(isUnlocked) {
          if(gridContainer) {
              gridContainer.style.opacity = '1';
              gridContainer.style.pointerEvents = 'auto'; // ปลดล็อกให้คลิกได้
              gridContainer.style.filter = 'none';
          }
          if(statusTextEl) {
              statusTextEl.innerHTML = iconUnlock + 'ปลดล็อกแล้ว'; 
              statusTextEl.style.color = '#34c759';
          }
      } else {
          if(gridContainer) {
              gridContainer.style.opacity = '0.4';
              gridContainer.style.pointerEvents = 'none'; // ล็อกไม่ให้คลิก
              gridContainer.style.filter = 'grayscale(0.8)';
          }
          if(statusTextEl) {
              statusTextEl.innerHTML = iconLock + 'รอตรวจสอบใบส่งของและภาพสินค้า'; 
              statusTextEl.style.color = '#ff3b30';
          }
      }
  }

  // --- Drag & Drop ระบบใหม่ ---
  window.setupNewDragDrop = function() {
      let dzDel = document.getElementById('dz_deliverySlip');
      let inpDel = document.getElementById('inp_deliverySlip');
      if(dzDel && inpDel) {
          dzDel.ondragover = e => { e.preventDefault(); dzDel.style.background = '#e0f0ff'; };
          dzDel.ondragleave = e => { e.preventDefault(); dzDel.style.background = '#f2f8ff'; };
          dzDel.ondrop = e => { 
              e.preventDefault(); 
              dzDel.style.background = '#f2f8ff'; 
              if(e.dataTransfer.files.length){ 
                  inpDel.files = e.dataTransfer.files; 
                  // 🌟 เรียกใช้ Cropper ทันทีเมื่อลากไฟล์มาวาง
                  openWaybillCropper(inpDel, 'verify', 'delModal_company', 'delModal_tracking', 'dz_deliverySlip');
                  handleDeliverySlipFiles(inpDel); 
              } 
          };
      }
      
      let dzArr = document.getElementById('dz_arrivalProduct');
      let inpArr = document.getElementById('inp_arrivalProduct');
      if(dzArr && inpArr) {
          dzArr.ondragover = e => { e.preventDefault(); dzArr.style.background = '#e0f0ff'; };
          dzArr.ondragleave = e => { e.preventDefault(); dzArr.style.background = '#f2f8ff'; };
          dzArr.ondrop = e => { e.preventDefault(); dzArr.style.background = '#f2f8ff'; if(e.dataTransfer.files.length){ inpArr.files = e.dataTransfer.files; handleArrivalProductFiles(inpArr); } };
      }
  }

  // ==========================================
  // 🌟 ฟังก์ชันคำนวณยอดค้างส่ง (หักจาก Lot อื่นๆ) (ดึงอ้างอิงเป็น "ชิ้น" อัตโนมัติ)
  // ==========================================
  window.getDynamicShipped = function(targetShipId, poId, uid) { 
      let orderQtyInPcs = 0;
      let po = sysData.purchaseOrders.find(p => p.poId === poId);
      if (po && po.itemData && po.itemData[uid]) {
          let p = sysData.products.find(x => x.uid === uid);
          if (p) {
              let sku = p.sku;
              let format = 'Pieces';
              let chkShow = false;
              if (po.skuData && po.skuData[sku]) {
                  format = po.skuData[sku].format || 'Pieces';
                  chkShow = po.skuData[sku].chkShow || false;
              }

              let mul = 1;
              let pSm = parseFloat(p.pkg_p_sm) || 1;
              let smLg = parseFloat(p.pkg_sm_lg) || 1;
              let lgC = parseFloat(p.pkg_lg_c) || 1;
              let pcsCtn = pSm * smLg * lgC;
              if (format === 'Pack') mul = smLg;
              else if (format === 'Set') mul = smLg;
              else if (format === 'Carton') mul = pcsCtn;

              let factOrder = parseFloat(po.itemData[uid].factoryOrder) || 0;
              let preOrder = parseFloat(po.itemData[uid].preOrderQty) || 0;
              let showOrderFormat = 0;
              if (chkShow) {
                  let showroomPcs = parseFloat(p.showroom) || 0;
                  showOrderFormat = Math.ceil(showroomPcs / mul);
              }
              // 🌟 แปลงยอดเป็นหน่วย "ชิ้น"
              orderQtyInPcs = (factOrder + preOrder + showOrderFormat) * mul;
          }
      }
      
      let remain = orderQtyInPcs; // เริ่มต้นจากยอดเต็ม (ชิ้น)
      
      if (sysData.shipments) {
        sysData.shipments.forEach(s => {
            if (s.shipId === targetShipId) return; 
            if (s.items) {
                s.items.forEach(i => {
                    if (i.uid === uid && (i.poId === poId || !poId)) {
                        if (i.actualQty !== undefined && i.actualQty !== null && i.actualQty !== '') {
                            let act = parseFloat(i.actualQty) || 0;
                            let dmg = parseFloat(i.damageQty) || 0;
                            remain -= (act + dmg); 
                        }
                    }
                });
            }
        });
      }
      
      return remain < 0 ? 0 : remain;
  };

  // ==========================================
  // 🌟 ระบบบันทึกติดตาม (Tracking Note)
  // ==========================================
  // 🌟 นำ "ใบสั่งซื้อ" และ "รหัสสินค้า" ออก แล้วเพิ่ม "แจ้งเตือน" เข้าไปแทน
  let activeReplyNote = null; // ตัวแปรเก็บข้อมูลข้อความที่กำลังจะถูก Reply
  const TRACK_TAGS = [
    "ติดตาม", "อัพเดท", "ปัญหา", "แจ้งเตือน", 
    "แก้ไข", "ยกเลิก", "สั่งสินค้า", "ด่วน", "เสร็จสิ้น", "สินค้าทดแทน"
  ];

