window.toggleNavDropdown = function(e) {
    if (e) e.stopPropagation();
    let menu = document.getElementById('navPreorderMenu');
    let arrow = document.getElementById('navPreorderArrow');
    
    let readyMenu = document.getElementById('navReadyMenu'); if(readyMenu) readyMenu.style.display = 'none';
    let preBkkMenu = document.getElementById('navPreorderBkkMenu'); if(preBkkMenu) preBkkMenu.style.display = 'none';

    if (menu) {
        if (menu.style.display === 'none' || menu.style.display === '') {
            menu.style.display = 'flex';
            if (arrow) arrow.style.transform = 'rotate(180deg)';
        } else {
            menu.style.display = 'none';
            if (arrow) arrow.style.transform = 'rotate(0deg)';
        }
    }
};

