// ดักจับการคลิกที่อื่นเพื่อปิด Dropdown ทั้งหมด
document.addEventListener('click', function(e) {
    if (!e.target.closest('.nav-dropdown')) {
        let menus = [
            { menuId: 'navPreorderMenu', arrowId: 'navPreorderArrow' },
            { menuId: 'navPreorderBkkMenu', arrowId: 'navPreorderBkkArrow' },
            { menuId: 'navReadyMenu', arrowId: 'navReadyArrow' }
        ];
        
        menus.forEach(m => {
            let menuEl = document.getElementById(m.menuId);
            let arrowEl = document.getElementById(m.arrowId);
            if (menuEl && menuEl.style.display === 'flex') {
                menuEl.style.display = 'none';
                if (arrowEl) arrowEl.style.transform = 'rotate(0deg)';
            }
        });
    }
});

