// 🌟 ฟังก์ชันจัดการตัวกรองสินค้า (พร้อมส่ง)
  window.updateFilterDropdownsReady = function() {
    if(!document.getElementById('flt_category_ready')) return;
    let currCat = document.getElementById('flt_category_ready').value;
    let currCol = document.getElementById('flt_color_ready').value;
    let currSiz = document.getElementById('flt_size_ready').value;
    let currPat = document.getElementById('flt_pattern_ready').value;

    let cats = new Set(), cols = new Set(), sizs = new Set(), pats = new Set();
    
    sysData.products.forEach(p => {
        let type = p.stockType || 'preorder';
        if (type !== 'ready') return; // กรองเอาเฉพาะ "พร้อมส่ง"

        let matchPrefix = (p.sku || '').match(/^[A-Za-z]{1,2}/);
        let prefix = matchPrefix ? matchPrefix[0].toUpperCase() : '';
        
        // 🌟 แก้ไข: บังคับให้หาชื่อหมวดหมู่ที่มาจาก stockType เป็น 'ready' เท่านั้น
        let catObj = sysData.categories.find(c => c.catCode === prefix && (c.stockType || 'preorder') === 'ready');
        
        let catName = '';
        if (catObj && catObj.name) {
            catName = catObj.name;
        } else if (p.category && p.category !== 'ไม่มีหมวดหมู่' && p.category !== 'ไม่ระบุ') {
            catName = p.category;
        } else {
            catName = prefix ? `ไม่ระบุ (รหัส ${prefix})` : 'ไม่ระบุ';
        }
        
        p._computedCategoryReady = catName; 
        cats.add(catName);

        if(p.color) cols.add(p.color);
        if(p.size) sizs.add(p.size);
        if(p.pattern) pats.add(p.pattern);
    });

    const buildOpts = (set, firstTxt) => {
        let h = `<option value="">${firstTxt}</option>`;
        [...set].sort().forEach(v => {
            let safeV = v.replace(/"/g, '&quot;');
            h += `<option value="${safeV}">${v}</option>`;
        });
        return h;
    };

    document.getElementById('flt_category_ready').innerHTML = buildOpts(cats, 'หมวดหมู่ทั้งหมด');
    document.getElementById('flt_color_ready').innerHTML = buildOpts(cols, 'สีทั้งหมด');
    document.getElementById('flt_size_ready').innerHTML = buildOpts(sizs, 'ขนาดทั้งหมด');
    document.getElementById('flt_pattern_ready').innerHTML = buildOpts(pats, 'แบบทั้งหมด');

    document.getElementById('flt_category_ready').value = currCat;
    document.getElementById('flt_color_ready').value = currCol;
    document.getElementById('flt_size_ready').value = currSiz;
    document.getElementById('flt_pattern_ready').value = currPat;
  };

// 🌟 ระบบลบรายการสำหรับหน้า 9
let isDeleteModeReady = false;
let selectedUIDsReady = [];

window.toggleDeleteModeReady = function() {
    isDeleteModeReady = !isDeleteModeReady;
    selectedUIDsReady = [];

    document.getElementById('btnAddCatReady').style.display = isDeleteModeReady ? 'none' : 'inline-flex';
    document.getElementById('btnAddProdReady').style.display = isDeleteModeReady ? 'none' : 'inline-flex';
    document.getElementById('btnToggleDeleteReady').style.display = isDeleteModeReady ? 'none' : 'inline-flex';
    
    document.getElementById('btnConfirmDeleteReady').style.display = isDeleteModeReady ? 'inline-flex' : 'none';
    document.getElementById('btnCancelDeleteReady').style.display = isDeleteModeReady ? 'inline-flex' : 'none';
    document.getElementById('btnConfirmDeleteReady').innerText = 'ยืนยันการลบ (0)';

    if (isDeleteModeReady) addSystemLog('เข้าสู่โหมดลบรายการ (สินค้าพร้อมส่ง)');
    renderProductBoardReady(); 
};

window.handleProductClickReady = function(uid) {
    if (typeof justDragged !== 'undefined' && justDragged) return;
    
    if (isDeleteModeReady) {
        const idx = selectedUIDsReady.indexOf(uid);
        if (idx > -1) selectedUIDsReady.splice(idx, 1);
        else selectedUIDsReady.push(uid);

        document.getElementById('btnConfirmDeleteReady').innerText = `ยืนยันการลบ (${selectedUIDsReady.length})`;
        renderProductBoardReady(); 
    } else {
        openProductDetail(uid);
    }
};

window.confirmDeleteReady = function() {
    if (selectedUIDsReady.length === 0) {
        showAppleAlert('แจ้งเตือน', 'กรุณาเลือกรายการที่ต้องการลบอย่างน้อย 1 รายการ');
        return;
    }
    
    showAppleConfirm('ยืนยันการลบ', `คุณต้องการลบข้อมูลสินค้าพร้อมส่ง ใช่หรือไม่?\nข้อมูลนี้จะถูกลบถาวร`, 'ลบข้อมูล', true, async function() {
        openModal('loader');
        try {
            const response = await fetch(`${CF_API_URL}/deleteProductsBatch`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ uids: selectedUIDsReady })
            });

            if (!response.ok) throw new Error("HTTP error " + response.status);
            const resData = await response.json();

            addSystemLog(resData.message + " (ผ่าน CF)");
            toggleDeleteModeReady(); 
            loadData(); 

        } catch (error) {
            closeModal('loader');
            showAppleAlert("ข้อผิดพลาด", "ไม่สามารถลบข้อมูลได้: " + error.message);
        }
    });
};

window.handleSearchEnterReady = function(event) {
    if (event.key === 'Enter') {
        let term = event.target.value.trim().toLowerCase();
        if (!term) return;

        let foundProduct = sysData.products.find(p => {
            let type = p.stockType || 'preorder';
            if (type !== 'ready') return false; // กรองเฉพาะหน้าพร้อมส่ง

            let sku = (p.sku || '').toLowerCase();
            let desc = (p.desc || '').toLowerCase();
            let remark = (p.remark || '').toLowerCase();
            return sku.includes(term) || desc.includes(term) || remark.includes(term);
        });

        if (foundProduct) {
            openProductDetail(foundProduct.uid);
            event.target.value = ''; 
        } else {
            showAppleAlert("ไม่พบข้อมูล", `ไม่พบสินค้าพร้อมส่งที่ตรงกับคำค้นหา:\n"${term}"`);
        }
    }
};

